<?php declare(strict_types=1); ?>
<div class="container page-space"><a class="back-link" href="/manage/api">← Acces API</a><div class="eyebrow">DEZVOLTATORI</div><h1 class="page-title">Aplicații și autorizări</h1><p><a href="/api/docs">Documentație și exemple</a> · <a href="/api/manifest.json">Manifest API</a></p>
<div class="admin-columns"><section class="panel"><h2>Aplicațiile tale</h2><?php if(!$clients):?><p>Nicio aplicație înregistrată.</p><?php endif?><?php foreach($clients as$c):?><article class="document-admin"><h3><?=e($c['name'])?></h3><p class="small mono break-word">client_id: <?=e($c['id'])?></p><p><?=($c['active']?'Activă':'Suspendată')?></p><ul><?php foreach(json_decode($c['redirect_uris_json'],true)as$uri):?><li class="small break-word"><?=e($uri)?></li><?php endforeach?></ul><?php if($c['active']):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="client.suspend"><input type="hidden" name="id" value="<?=e($c['id'])?>"><button class="btn btn-outline-primary btn-sm">Suspendă aplicația</button></form><?php endif?></article><?php endforeach?></section>
<section class="panel"><h2>Înregistrează o aplicație</h2><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="client.create"><label>Denumire<input class="form-control" name="name" maxlength="120" required></label><label>Adrese de revenire, câte una pe rând<textarea class="form-control" name="redirect_uris" rows="4" maxlength="12000" required placeholder="https://aplicatia-ta.ro/callback"></textarea></label><fieldset><legend class="h6">Permisiuni pe care aplicația le poate solicita</legend><?php foreach(\App\Domain\OAuth::SCOPES as$scope):?><label class="check-label"><input type="checkbox" name="scopes[]" value="<?=e($scope)?>" <?=$scope==='read'?'checked':''?>> <?=e($scope)?></label><?php endforeach?></fieldset><p class="small muted">Fiecare persoană aprobă separat accesul la o organizație sau familie. Aplicația folosește PKCE S256 și nu primește un secret de client.</p><button class="btn btn-primary" type="submit">Înregistrează aplicația</button></form></section></div>
<section class="panel"><h2>Acces acordat de tine</h2><?php if(!$grants):?><p>Nicio autorizare acordată.</p><?php endif?><?php foreach($grants as$g):?><article class="document-admin"><h3><?=e($g['name'])?></h3><p><?=e(implode(', ',json_decode($g['scopes_json'],true)))?> · expiră <?=e(substr($g['expires_at'],0,10))?></p><?php if($g['revoked_at']):?><span class="tag">Acces retras</span><?php else:?><form method="post"><?=csrf()?><input type="hidden" name="action" value="grant.revoke"><input type="hidden" name="id" value="<?=e($g['id'])?>"><button class="btn btn-outline-primary btn-sm">Retrage accesul</button></form><?php endif?></article><?php endforeach?></section></div>
